fn frame(t: i32) {
    let data = [23, 8, 31, 15, 27];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x101010);
    let bw: i32 = w / 5;
    let mut i: i32 = 0;
    while i < 5 {
        let v: i32 = data[i];
        let bh: i32 = v * 4;
        host::display::fill_rect(i * bw + 4, h - bh - 20, bw - 8, bh, 0x00b0ff);
        host::display::draw_number(i * bw + 8, h - bh - 34, v, 0xffffff, 1);
        i = i + 1;
    }
    host::display::present();
}
